// Orbit Dodge Game
// Canvas element with id="game" is assumed to exist in the HTML.
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas with id "game" not found');
  const ctx = canvas.getContext('2d');

  // Full‑screen canvas handling
  const resize = () => {
    canvas.width = canvas.clientWidth;
    canvas.height = canvas.clientHeight;
  };
  window.addEventListener('resize', resize);
  resize();

  // Game state
  const state = {
    // satellite orbit radius (distance from centre)
    radius: Math.min(canvas.width, canvas.height) * 0.35,
    // orbital angle in radians
    angle: 0,
    // orbital speed (radians per frame)
    angularVelocity: 0.02,
    // speed multiplier (for acceleration/deceleration)
    speedFactor: 1,
    // debris array
    debris: [],
    // time since start (seconds)
    time: 0,
    // game over flag
    over: false,
  };

  // Input handling – left/right arrows rotate, up/down adjust speed
  const keys = {};
  window.addEventListener('keydown', e => { keys[e.key] = true; });
  window.addEventListener('keyup', e => { keys[e.key] = false; });

  // Debris generation
  const spawnDebris = () => {
    const angle = Math.random() * Math.PI * 2;
    const distance = Math.max(canvas.width, canvas.height); // start outside view
    const speed = 1 + Math.random() * 2; // pixels per frame towards centre
    state.debris.push({ angle, distance, speed });
  };

  // Collision detection (simple distance check)
  const checkCollision = () => {
    const satX = canvas.width / 2 + state.radius * Math.cos(state.angle);
    const satY = canvas.height / 2 + state.radius * Math.sin(state.angle);
    for (const d of state.debris) {
      const dX = canvas.width / 2 + d.distance * Math.cos(d.angle);
      const dY = canvas.height / 2 + d.distance * Math.sin(d.angle);
      const dx = satX - dX;
      const dy = satY - dY;
      const distSq = dx * dx + dy * dy;
      const collisionDist = 10; // satellite radius ~5, debris radius ~5
      if (distSq < collisionDist * collisionDist) {
        state.over = true;
        break;
      }
    }
  };

  // Main loop
  const loop = (timestamp) => {
    if (state.over) {
      ctx.fillStyle = 'black';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = 'white';
      ctx.font = '24px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2 - 20);
      ctx.fillText(`Survived: ${state.time.toFixed(1)}s`, canvas.width / 2, canvas.height / 2 + 20);
      return; // stop animation
    }

    // Update time
    state.time += 1 / 60; // assume ~60fps

    // Input handling
    if (keys['ArrowLeft']) state.angle -= state.angularVelocity * state.speedFactor;
    if (keys['ArrowRight']) state.angle += state.angularVelocity * state.speedFactor;
    if (keys['ArrowUp']) state.speedFactor = Math.min(state.speedFactor + 0.01, 3);
    if (keys['ArrowDown']) state.speedFactor = Math.max(state.speedFactor - 0.01, 0.5);

    // Spawn debris periodically
    if (Math.random() < 0.02) spawnDebris(); // ~1 per 50 frames

    // Update debris positions
    for (let i = state.debris.length - 1; i >= 0; i--) {
      const d = state.debris[i];
      d.distance -= d.speed;
      if (d.distance < 0) {
        state.debris.splice(i, 1); // remove passed debris
      }
    }

    // Collision check
    checkCollision();

    // Rendering
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw planet at centre
    ctx.fillStyle = '#2c3e50';
    ctx.beginPath();
    ctx.arc(canvas.width / 2, canvas.height / 2, 30, 0, Math.PI * 2);
    ctx.fill();

    // Draw satellite
    const satX = canvas.width / 2 + state.radius * Math.cos(state.angle);
    const satY = canvas.height / 2 + state.radius * Math.sin(state.angle);
    ctx.fillStyle = '#e74c3c';
    ctx.beginPath();
    ctx.arc(satX, satY, 5, 0, Math.PI * 2);
    ctx.fill();

    // Draw debris
    ctx.fillStyle = '#ecf0f1';
    for (const d of state.debris) {
      const x = canvas.width / 2 + d.distance * Math.cos(d.angle);
      const y = canvas.height / 2 + d.distance * Math.sin(d.angle);
      ctx.beginPath();
      ctx.arc(x, y, 5, 0, Math.PI * 2);
      ctx.fill();
    }

    // Draw score (time survived)
    ctx.fillStyle = 'white';
    ctx.font = '16px sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText(`Time: ${state.time.toFixed(1)}s`, 10, 20);

    requestAnimationFrame(loop);
  };

  requestAnimationFrame(loop);
})();
